/**
 * You can store multiple cards on a customer in order to charge the customer
 * later. You can also store multiple debit cards on a recipient in order to
 * transfer to those cards later.
 * 
 * Related guide: [Card payments with Sources](https://stripe.com/docs/sources/cards)
 */
const Card = z.object({
'account': z.union([z.string(), z.lazy(() => Account)]).optional(),
'address_city': z.string().nullable(),
'address_country': z.string().nullable(),
'address_line1': z.string().nullable(),
'address_line1_check': z.string().nullable(),
'address_line2': z.string().nullable(),
'address_state': z.string().nullable(),
'address_zip': z.string().nullable(),
'address_zip_check': z.string().nullable(),
'allow_redisplay': z.enum(['always', 'limited', 'unspecified']).nullable().optional(),
'available_payout_methods': z.array(z.enum(['instant', 'standard'])).nullable().optional(),
'brand': z.string(),
'brand_product': z.string().nullable().optional(),
'country': z.string().nullable(),
'currency': z.string().nullable().optional(),
'customer': z.union([z.string(), z.lazy(() => Customer), DeletedCustomer]).optional(),
'cvc_check': z.string().nullable(),
'default_for_currency': z.boolean().nullable().optional(),
'description': z.string().optional(),
'dynamic_last4': z.string().nullable(),
'exp_month': z.number().int(),
'exp_year': z.number().int(),
'fingerprint': z.string().nullable().optional(),
'funding': z.string(),
'id': z.string(),
'iin': z.string().optional(),
'issuer': z.string().optional(),
'last4': z.string(),
'metadata': z.record(z.string(), z.string()).nullable(),
'name': z.string().nullable(),
'networks': TokenCardNetworks.optional(),
'object': z.enum(['card']),
'regulated_status': z.enum(['regulated', 'unregulated']).nullable(),
'status': z.string().nullable().optional(),
'tokenization_method': z.string().nullable()
});

export const parseCard = (value) => Card.parse(value);

