'application': z.union([z.string(), Application]),
'attach_to_self': z.boolean().optional(),
'automatic_payment_methods': z.union([PaymentFlowsAutomaticPaymentMethodsSetupIntent]),
'cancellation_reason': z.enum(['abandoned', 'duplicate', 'requested_by_customer']).nullable(),
'client_secret': z.string().nullable(),
'created': z.number().int(),
'customer': z.union([z.string(), z.lazy(() => Customer), DeletedCustomer]),
'customer_account': z.string().nullable().optional(),
'description': z.string().nullable(),
'excluded_payment_method_types': z.array(z.enum(['acss_debit', 'affirm', 'afterpay_clearpay', 'alipay', 'alma', 'amazon_pay', 'au_becs_debit', 'bacs_debit', 'bancontact', 'billie', 'blik', 'boleto', 'card', 'cashapp', 'crypto', 'customer_balance', 'eps', 'fpx', 'giropay', 'gopay', 'grabpay', 'id_bank_transfer', 'ideal', 'kakao_pay', 'klarna', 'konbini', 'kr_card', 'mb_way', 'mobilepay', 'multibanco', 'naver_pay', 'nz_bank_account', 'oxxo', 'p24', 'pay_by_bank', 'payco', 'paynow', 'paypal', 'paypay', 'payto', 'pix', 'promptpay', 'qris', 'rechnung', 'revolut_pay', 'samsung_pay', 'satispay', 'sepa_debit', 'shopeepay', 'sofort', 'stripe_balance', 'swish', 'twint', 'us_bank_account', 'wechat_pay', 'zip'])).nullable(),
'flow_directions': z.array(z.enum(['inbound', 'outbound'])).nullable().optional(),
'id': z.string(),
'last_setup_error': z.union([z.lazy(() => ApiErrors)]),
'latest_attempt': z.union([z.string(), z.lazy(() => SetupAttempt)]),
'livemode': z.boolean(),
'mandate': z.union([z.string(), z.lazy(() => Mandate)]),
'metadata': z.record(z.string(), z.string()).nullable(),
'next_action': z.union([SetupIntentNextAction]),
'object': z.enum(['setup_intent']),
