'object': z.enum(['checkout.session']),
'optional_items': z.array(PaymentPagesCheckoutSessionOptionalItem).nullable().optional(),
'origin_context': z.enum(['mobile_app', 'web']).nullable(),
'payment_intent': z.union([z.string(), z.lazy(() => PaymentIntent)]),
'payment_link': z.union([z.string(), PaymentLink]),
'payment_method_collection': z.enum(['always', 'if_required']).nullable(),
